\begin{tikzpicture}[
        node distance=1.5cm and 1.8cm,
        caja/.style={
            draw=BrandBlue,
            thick,
            rounded corners=3pt,
            fill=IdeaBody,
            minimum width=3.6cm,
            minimum height=1.0cm,
            align=center
        },
        subcaja/.style={
            draw=PracticeTitle,
            thick,
            rounded corners=3pt,
            fill=PracticeBody,
            minimum width=3.6cm,
            minimum height=1.0cm,
            align=center
        },
        flecha/.style={
            -{Latex[length=3mm]},
            thick,
            BrandBlue
        },
        nota/.style={
            font=\small,
            align=center,
            text width=3.8cm
        }
        ]


        \node[caja] (flujo)
        {Flujo normal\\\small comportamiento base};


        \node[subcaja, below left=1.6cm and 3.2cm of flujo] (position)
        {Position\\\small altera o ancla elementos};

        \node[subcaja, below=1.6cm of flujo] (flex)
        {Flexbox\\\small un eje dominante};

        \node[subcaja, below right=1.6cm and 3.2cm of flujo] (grid)
        {Grid\\\small filas y columnas};


        \draw[flecha] (flujo) -- (position);
        \draw[flecha] (flujo) -- (flex);
        \draw[flecha] (flujo) -- (grid);


        \node[nota, below=0.45cm of position]
        {Útil para superposición, desplazamiento y elementos anclados.};

        \node[nota, below=0.45cm of flex]
        {Adecuado cuando la distribución se entiende principalmente como fila o columna.};

        \node[nota, below=0.45cm of grid]
        {Adecuado cuando deben controlarse filas y columnas simultáneamente.};

    \end{tikzpicture}

