\begin{tikzpicture}[
        item/.style={
            draw=PracticeTitle,
            thick,
            fill=PracticeBody,
            minimum width=2.1cm,
            minimum height=0.85cm,
            align=center
        },
        imp/.style={
            draw=WarnTitle,
            thick,
            dashed,
            fill=WarnBody,
            minimum width=2.1cm,
            minimum height=0.85cm,
            align=center
        },
        label/.style={
            font=\small\bfseries
        }
        ]





        \node[font=\bfseries] at (4.1,4.1)
        {Cuadrícula explícita};

        \node[
        font=\small,
        text=BrandBlue
        ] at (4.1,3.55)
        {\texttt{grid-template-columns} + \texttt{grid-template-rows}};

        \foreach \x in {1.2,4.1,7}{
            \node[item] at (\x,2.75) {item};
        }





        \draw[
        WarnTitle,
        dashed,
        very thick,
        rounded corners=2pt
        ] (0,0.65) rectangle (8.2,2.0);

        \foreach \x in {1.2,4.1,7}{
            \node[imp] at (\x,1.35) {item};
        }

        \node[
        font=\small\bfseries,
        text=WarnTitle
        ] at (4.1,0.28)
        {Fila implícita};

        \node[
        font=\small,
        align=center,
        text width=8cm
        ] at (4.1,-0.75)
        {
            Grid crea esta fila automáticamente porque existen
            más elementos de los que caben en la cuadrícula explícita.
        };

    \end{tikzpicture}

\begin{tikzpicture}[
    item/.style={draw=PracticeTitle, thick, fill=PracticeBody, align=center},
    principal/.style={draw=WarnTitle, very thick, fill=WarnBody, align=center}
]
    \draw[BrandBlue, very thick] (0,0) rectangle (10,4);
    \draw[BrandBlue] (3.3,0)--(3.3,4);
    \draw[BrandBlue] (6.6,0)--(6.6,4);
    \draw[BrandBlue] (0,2)--(10,2);

    \foreach \x/\n in {0/1,3.3/2,6.6/3,10/4}{
        \node[above] at (\x,4) {\n};
    }

    \node[principal, minimum width=6.2cm, minimum height=1.55cm] at (3.3,3)
        {\texttt{grid-column: 1 / 3}};
    \node[item, minimum width=2.8cm, minimum height=1.55cm] at (8.3,3) {item};
    \node[item, minimum width=2.8cm, minimum height=1.55cm] at (1.65,1) {item};
    \node[item, minimum width=2.8cm, minimum height=1.55cm] at (4.95,1) {item};
    \node[item, minimum width=2.8cm, minimum height=1.55cm] at (8.3,1) {item};
\end{tikzpicture}

