        font=\ttfamily\small,
        align=center
        ] at (2.3,0.5)
        {
            justify-items \\ align-items
        };

        \node[
        font=\small,
        align=center,
        text width=4.4cm
        ] at (2.3,-0.5)
        {
            Cada item se mueve dentro de su propia celda
        };





        \node[label] at (8.1,3.9)
        {Alineación de la cuadrícula};

        \draw[container] (5.7,1.2) rectangle (10.5,3.4);


        \draw[gridbox] (6.8,1.75) rectangle (9.4,2.85);


        \draw[PracticeTitle] (8.1,1.75) -- (8.1,2.85);
        \draw[PracticeTitle] (6.8,2.3) -- (9.4,2.3);

        \node[
        font=\ttfamily\small,
        align=center
        ] at (8.1,0.5)
        {
            justify-content \\ align-content
        };

        \node[
        font=\small,
        align=center,
        text width=4.6cm
        ] at (8.1,-0.5)
        {
            Se mueve la cuadrícula completa dentro del contenedor
        };

    \end{tikzpicture}

